import json

incident_id = inputs.get('incident_id') or inputs.get('incidentId')
if not incident_id:
    raise ValueError('incident_id is required')

result = tool.run_safe('security_report_generate', incident_id=incident_id, format='markdown')
if not result['success']:
    outputs['success'] = False
    outputs['error'] = result['error']
else:
    try:
        report = json.loads(result['text'])
    except Exception:
        report = {'content': result.get('text', '')}
    outputs['success'] = True
    outputs['incident_id'] = incident_id
    outputs['report'] = report.get('content', '') if isinstance(report, dict) else str(report)
